'use strict';
(function(){
 const currentKey='working-session-v1',previousKey='working-session-previous-v1';
 let database,ready=false,watching=false,restored=false,blocked=false,warning=false,timer,saving,again=false,lastSignature='',savedAt=0,writes=0,lastError='',nextImage=1;
 const ids=new WeakMap(),versions=new WeakMap(),blobs=new WeakMap();const invalidKeys=new Set();let installedResolve;const installed=new Promise(r=>installedResolve=r);
 const clone=x=>x==null?x:JSON.parse(JSON.stringify(x));
 function db(){if(!database)database=new Promise((resolve,reject)=>{const r=indexedDB.open('fragment-editor',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('preferences'))r.result.createObjectStore('preferences')};r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();database=null};resolve(r.result)};r.onerror=()=>{database=null;reject(r.error)}});return database}
 async function read(key){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('preferences','readonly'),r=tx.objectStore('preferences').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
 async function write(record){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('preferences','readwrite'),store=tx.objectStore('preferences'),old=store.get(currentKey);old.onsuccess=()=>{if(old.result&&!invalidKeys.has(currentKey))store.put(old.result,previousKey);store.put(record,currentKey)};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
 function picture(image,pool){if(!ids.has(image))ids.set(image,nextImage++);const key=ids.get(image);pool.set(key,image);return key}
 function layerMeta(layer,pool){const {img,children,...rest}=layer;return{...clone(rest),img:picture(img,pool),...(children?{children:children.map(l=>layerMeta(l,pool))}:{})}}
 function stateMeta(state,pool){return{base:picture(state.base,pool),layers:state.layers.map(l=>layerMeta(l,pool)),active:state.active,selected:[...(state.selected||[])],pending:clone(state.pending),filename:state.filename,visible:state.visible,sourceBytes:state.sourceBytes}}
 function capture(){const pool=new Map(),current=stateMeta({base,layers,active,selected,pending,filename:$('filename').textContent,visible:$('baseVisible').checked,sourceBytes:globalThis.FragmentExport?.sourceBytes()},pool);
  const meta={current,history:history.map(s=>stateMeta(s,pool)),redo:(globalThis.FragmentHistory?.redoStates()||[]).map(s=>stateMeta(s,pool)),seq,mode,selection:clone(selection),lasso:typeof lassoPoints==='undefined'?[]:clone(lassoPoints),selectionShape:$('selectionShape')?.value,splitTolerance:$('splitTolerance').value,backgroundTolerance:$('backgroundTolerance').value,view:typeof viewState==='undefined'?null:{...viewState},layoutProfile:globalThis.FragmentLayoutProfiles?.get()};
  meta.imageVersions=[...pool].map(([key,image])=>[key,versions.get(image)||0]);return{meta,pool,signature:JSON.stringify(meta)};
 }
 function encode(image){if(!blobs.has(image))blobs.set(image,(async()=>{const width=image.width,height=image.height,data=image.getContext('2d',{willReadFrequently:true}).getImageData(0,0,width,height).data,raw=new Blob([data]);if(typeof CompressionStream!=='undefined'){const blob=await new Response(raw.stream().pipeThrough(new CompressionStream('deflate'))).blob();return{width,height,encoding:'rgba-deflate',blob}}return{width,height,encoding:'rgba',blob:raw}})());return blobs.get(image)}
 function invalidate(){const visit=l=>{blobs.delete(l.img);versions.set(l.img,(versions.get(l.img)||0)+1);l.children?.forEach(visit)};blobs.delete(base);versions.set(base,(versions.get(base)||0)+1);layers.forEach(visit)}
 function schedule(){if(!ready||blocked)return;clearTimeout(timer);timer=setTimeout(()=>flush(),220)}
 async function flush(){clearTimeout(timer);if(!ready||blocked)return false;if(saving){again=true;await saving;return flush()}const snap=capture();if(snap.signature===lastSignature)return true;
  saving=(async()=>{try{const images=await Promise.all([...snap.pool].map(async([key,image])=>({key,...await encode(image)})));if(capture().signature!==snap.signature){again=true;return false}const at=Date.now();await write({schema:2,at,meta:snap.meta,images});lastSignature=snap.signature;invalidKeys.delete(currentKey);savedAt=at;writes++;lastError='';warning=false;return true}catch(error){lastError=String(error?.message||error);if(!warning){warning=true;toast('Автосохранение недоступно. Сохраните проект в файл.')}return false}})();
  const result=await saving;saving=null;if(again){again=false;return flush()}return result;
 }
 async function unpack(record){if(![1,2].includes(record?.schema)||!record.meta?.current||!Array.isArray(record.images)||record.images.length>8000)throw Error('Неверная сохранённая сессия');const pictures=new Map(),revision=new Map(record.meta.imageVersions||[]);
  for(const item of record.images){if(!(item.blob instanceof Blob))throw Error('Нет изображения');let result;if(item.encoding==='rgba'||item.encoding==='rgba-deflate'){const {width,height}=item;if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>12000||height>12000||width*height>36000000)throw Error('Размер изображения');const stream=item.encoding==='rgba-deflate'?item.blob.stream().pipeThrough(new DecompressionStream('deflate')):item.blob.stream(),bytes=new Uint8ClampedArray(await new Response(stream).arrayBuffer());if(bytes.length!==width*height*4)throw Error('Повреждены пиксели');result=off(width,height);const ctx=result.getContext('2d',{willReadFrequently:true}),data=ctx.createImageData(width,height);data.data.set(bytes);ctx.putImageData(data,0,0);blobs.set(result,Promise.resolve({width,height,encoding:item.encoding,blob:item.blob}))}else{let url;try{url=URL.createObjectURL(item.blob);const image=await loadImg(url);if(image.width>12000||image.height>12000||image.width*image.height>36000000)throw Error('Размер изображения');result=off(image.width,image.height);result.getContext('2d').drawImage(image,0,0)}finally{if(url)URL.revokeObjectURL(url)}}pictures.set(item.key,result);ids.set(result,item.key);versions.set(result,revision.get(item.key)||0);nextImage=Math.max(nextImage,item.key+1)}
  function restoreState(s){let count=0;function layer(l,depth=0){if(++count>300||depth>12||![l.x,l.y,l.scale,l.angle,l.opacity].every(Number.isFinite)||l.scale<=0||!pictures.has(l.img))throw Error('Повреждён слой');return{...l,img:pictures.get(l.img),...(l.children?{children:l.children.map(child=>layer(child,depth+1))}:{})}}if(!pictures.has(s.base)||!Array.isArray(s.layers)||s.layers.length>150)throw Error('Повреждён проект');return{...s,base:pictures.get(s.base),layers:s.layers.map(l=>layer(l))}}
  const meta=record.meta;return{meta,current:restoreState(meta.current),history:(meta.history||[]).slice(-12).map(restoreState),redo:(meta.redo||[]).slice(-12).map(restoreState)};
 }
 async function restore(initialBase){let found=false;const main=document.querySelector('main');try{for(const key of [currentKey,previousKey]){let record;try{record=await read(key);if(!record)continue;found=true;main.inert=true;main.setAttribute('aria-busy','true');$('exampleLoading').hidden=false;$('exampleLoading').textContent='Восстанавливаем проект…';const state=await unpack(record);await installed;if(base!==initialBase||layers.length||selection)return false;
    base=state.current.base;layers=state.current.layers;active=state.current.active;selected=new Set((state.current.selected||[]).filter(id=>layers.some(l=>l.id===id)));if(active!=null&&!selected.has(active))active=[...selected].at(-1)??null;pending=state.current.pending;history=state.history;globalThis.FragmentHistory?.restoreRedo(state.redo);seq=Math.max(state.meta.seq||0,...layers.map(l=>l.id));selection=state.meta.selection;lassoPoints=state.meta.lasso||[];if($('selectionShape')&&state.meta.selectionShape)$('selectionShape').value=state.meta.selectionShape;$('closeLasso').disabled=lassoPoints.length<3;
    $('filename').textContent=state.current.filename||'Проект';$('baseVisible').checked=state.current.visible!==false;globalThis.FragmentExport?.setSourceBytes(state.current.sourceBytes);for(const id of ['splitTolerance','backgroundTolerance'])if(state.meta[id]!=null){$(id).value=state.meta[id];$(id+'Value').textContent=state.meta[id]}
    if(typeof viewState!=='undefined'){Object.assign(viewState,{zoom:1,panX:0,panY:0});if(state.meta.layoutProfile===globalThis.FragmentLayoutProfiles?.get()&&state.meta.view)Object.assign(viewState,state.meta.view)}splitSession=null;setMode(['move','select','objects'].includes(state.meta.mode)?state.meta.mode:'move');ui();$('status').textContent='Проект восстановлен · слоёв: '+layers.length;restored=true;savedAt=record.at;lastSignature=capture().signature;return true;
   }catch(error){if(record)invalidKeys.add(key);lastError=String(error?.message||error)}}if(found){blocked=true;toast('Не удалось восстановить проект. Сохранённая копия оставлена.')}return false;}finally{main.inert=false;main.removeAttribute('aria-busy')}
 }
 function watch(){if(watching)return;watching=true;const originalRender=render;render=function(...args){const result=originalRender(...args);schedule();return result};const originalCheckpoint=checkpoint;checkpoint=function(...args){invalidate();const result=originalCheckpoint(...args);schedule();return result};document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flush()});addEventListener('pagehide',()=>flush());installedResolve();if(ready)schedule()}
 window.FragmentSession={restore,watch,flush,markReady:()=>{ready=true;if(watching)schedule()},allowNewDocument:()=>{blocked=false},status:()=>({ready,restored,saving:!!saving,savedAt,writes,error:lastError})};
})();
